use proptest::prelude::*;
use solution::Spans;
use std::collections::BTreeSet;

fn spans(s: &Spans) -> Vec<(i64, i64)> {
    (0..s.count()).map(|i| (s.first(i).unwrap(), s.last(i).unwrap())).collect()
}

#[test]
fn basics() {
    let mut s = Spans::new();
    s.push(1, 5);
    s.push(7, 7);
    assert!(s.remove(7));
    assert_eq!(spans(&s), vec![(1, 5)]);
    assert!(s.remove(1));
    assert!(s.remove(5));
    assert!(s.remove(3));
    assert_eq!(spans(&s), vec![(2, 2), (4, 4)]);
    assert!(!s.remove(3));
}

#[test]
fn full_split_refused() {
    let mut s = Spans::new();
    for i in 0..8 {
        s.push(10 * i, 10 * i + 5);
    }
    assert!(!s.remove(12));
    assert_eq!(s.count(), 8);
    assert!(s.remove(10));
    assert!(s.remove(15));
    let mut t = Spans::new();
    t.push(i64::MIN, i64::MAX);
    assert!(t.remove(i64::MAX));
    assert!(t.remove(i64::MIN));
    assert!(t.remove(0));
    assert_eq!(t.count(), 2);
}

proptest! {
    #[test]
    fn model(ops in proptest::collection::vec((any::<bool>(), 0i64..40), 0..60)) {
        let mut s = Spans::new();
        let mut m: BTreeSet<i64> = BTreeSet::new();
        for (ins, x) in ops {
            if ins {
                // rebuild via push from model plus x when it keeps a valid list
                let mut m2 = m.clone();
                m2.insert(x);
                let mut t = Spans::new();
                let mut ok = true;
                let mut it = m2.iter().peekable();
                while let Some(&a) = it.next() {
                    let mut b = a;
                    while let Some(&&n) = it.peek() { if n == b + 1 { b = n; it.next(); } else { break; } }
                    ok &= t.push(a, b);
                }
                if ok { s = t; m = m2; }
            } else {
                let before = spans(&s);
                let r = s.remove(x);
                if r {
                    prop_assert!(m.remove(&x));
                } else {
                    prop_assert_eq!(spans(&s), before);
                    prop_assert!(!m.contains(&x) || s.count() == 8);
                }
            }
            let v = spans(&s);
            prop_assert!(v.len() <= 8);
            for w in v.windows(2) { prop_assert!(w[0].1 + 1 < w[1].0); }
            for &(a, b) in &v { prop_assert!(a <= b); }
            let mut got = BTreeSet::new();
            for (a, b) in v { for k in a..=b { got.insert(k); } }
            prop_assert_eq!(&got, &m);
        }
    }
}

