//! A binary min-heap of at most 8 `i64` values.

/// The values `a[0..len]` in heap order.
///
/// Invariant (every method may rely on it and must keep it): `len <= 8`,
/// and no value is smaller than its parent's: `a[(i - 1) / 2] <= a[i]` for
/// `0 < i < len`. So `a[0]` is the smallest.
#[derive(Clone, Debug)]
pub struct Heap {
    a: [i64; 8],
    len: usize,
}

impl Heap {
    pub fn new() -> Heap {
        Heap { a: [0; 8], len: 0 }
    }

    pub fn size(&self) -> usize {
        self.len
    }

    /// The smallest value.
    pub fn peek(&self) -> Option<i64> {
        if self.len == 0 {
            None
        } else {
            Some(self.a[0])
        }
    }

    /// Adds `x`; `false` when full: the value is not stored.
    pub fn push(&mut self, x: i64) -> bool {
        if self.len == 8 {
            return false;
        }
        let mut k = self.len;
        self.a[k] = x;
        self.len += 1;
        while k > 0 && self.a[(k - 1) / 2] > self.a[k] {
            let p = (k - 1) / 2;
            self.a.swap(p, k);
            k = p;
        }
        true
    }

    /// Removes and returns the smallest value; `None` when empty.
    pub fn pop(&mut self) -> Option<i64> {
        if self.len == 0 {
            return None;
        }
        let top = self.a[0];
        self.len -= 1;
        self.a[0] = self.a[self.len];
        self.a[self.len] = 0;
        let mut k = 0;
        loop {
            let l = 2 * k + 1;
            let r = l + 1;
            let mut m = k;
            if l < self.len && self.a[l] < self.a[m] {
                m = l;
            }
            if r < self.len && self.a[r] < self.a[m] {
                m = r;
            }
            if m == k {
                break;
            }
            self.a.swap(m, k);
            k = m;
        }
        Some(top)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn pop_sorted(v in proptest::collection::vec(any::<i64>(), 0..12)) {
            let mut h = Heap::new();
            let mut model = Vec::new();
            for x in v {
                if h.push(x) { model.push(x); }
            }
            model.sort();
            for x in model {
                prop_assert_eq!(h.pop(), Some(x));
            }
            prop_assert_eq!(h.pop(), None);
            prop_assert_eq!(h.size(), 0);
        }
    }
}

